"""Stage 3: rate limiting (docs/ratelimit.md)."""

import math
from fractions import Fraction

from frontdoor.ratelimit.clients import client_address, key_text
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"


class State:
    def __init__(self, config):
        self.limits = config.section("limit", [])
        self.trusted = config.section("clients", ())
        self.buckets = [{} for _ in self.limits]
        self.limited = {lim.name: 0 for lim in self.limits}
        self.now = None


def setup(config):
    return State(config)


def _key_value(part, ctx, addr):
    if part == "tenant":
        return ctx.tenant
    if part == "client":
        return key_text(addr)
    if part == "route":
        return ctx.route.name
    if part == "method":
        return ctx.request.method.upper()
    v = ctx.request.headers.get(part[len("header:"):])
    if v is None:
        return None
    return v.strip(" \t") or None


def _covers(lim, ctx, addr):
    if lim.routes is not None and ctx.route.name not in lim.routes:
        return None
    method = ctx.request.method.upper()
    if lim.methods is not None and method not in lim.methods:
        return None
    if addr is not None and not isinstance(addr, str) and any(addr in n for n in lim.exempt):
        return None
    key = []
    for part in lim.key:
        v = _key_value(part, ctx, addr)
        if v is None:
            return None
        key.append(v)
    return tuple(key)


def _seconds_up(ms) -> int:
    return math.ceil(Fraction(ms) / 1000)


def handle(ctx, state):
    if not state.limits:
        return None
    ts = ctx.request.ts_ms
    state.now = ts if state.now is None else max(state.now, ts)
    now = state.now
    addr = client_address(ctx.request, state.trusted)
    method = ctx.request.method.upper()
    covering = []
    for i, lim in enumerate(state.limits):
        key = _covers(lim, ctx, addr)
        if key is None:
            continue
        st = state.buckets[i].get(key)
        if st is None:
            st = state.buckets[i][key] = new_state(lim, now)
        st.refill(now)
        covering.append((lim, st, lim.cost_of(method)))
    if not covering:
        return None
    refusing = [(lim, st, c) for lim, st, c in covering if not st.allows(c)]
    if not refusing:
        for lim, st, c in covering:
            st.charge(c)
        lim, st, _ = min(covering, key=lambda e: e[1].remaining())
        _set_headers(ctx, lim, st, now)
        return None
    for lim, _, _ in refusing:
        state.limited[lim.name] += 1
    best = None
    best_wait = None
    for lim, st, c in refusing:
        if c > lim.capacity:
            best = (lim, st, c)
            best_wait = None
            break
        w = st.wait(c, now)
        if best is None or w > best_wait:
            best, best_wait = (lim, st, c), w
    lim, st, c = best
    _set_headers(ctx, lim, st, now)
    if best_wait is not None:
        ctx.headers["Retry-After"] = str(max(1, _seconds_up(best_wait)))
    return 429


def _set_headers(ctx, lim, st, now):
    ctx.headers["RateLimit-Limit"] = str(lim.capacity)
    ctx.headers["RateLimit-Remaining"] = str(st.remaining())
    ctx.headers["RateLimit-Reset"] = str(st.reset(now))


def summary(state):
    if not state.limits:
        return {}
    return {"limited": dict(state.limited)}
